import{_ as a,o as r,c as e,ae as d}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"架构师-备考 论文写作-十段式论文模板与常见问题","description":"","frontmatter":{"title":"架构师-备考 论文写作-十段式论文模板与常见问题"},"headers":[],"relativePath":"论文写作/十段式论文模板与常见问题.md","filePath":"论文写作/十段式论文模板与常见问题.md"}'),o={name:"论文写作/十段式论文模板与常见问题.md"};function l(i,t,n,h,s,u){return r(),e("div",null,[...t[0]||(t[0]=[d('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 十段式论文模板（摘要→背景→子题→正文→结尾）</li><li>[x] 各段字数分配与写作要点</li><li>[x] 项目选择策略（选什么/不能选什么/零基础怎么选）</li><li>[x] 论文写作常见 7 大问题及应对</li><li>[x] 论点构建方法论（3-5 论点/高频考点论点库）</li><li>[x] 历年真题趋势与分类</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、十段式论文模板-★" tabindex="-1">一、十段式论文模板 ★ <a class="header-anchor" href="#一、十段式论文模板-★" aria-label="Permalink to &quot;一、十段式论文模板 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>段落</th><th style="text-align:center;">字数</th><th>内容要点</th></tr></thead><tbody><tr><td><strong>摘要</strong></td><td style="text-align:center;">~300</td><td>项目背景（时间+项目+岗位+功能）+ 回应主题（概括正文步骤）</td></tr><tr><td><strong>项目背景①</strong></td><td style="text-align:center;">200</td><td>项目大背景与问题引出</td></tr><tr><td><strong>项目背景②</strong></td><td style="text-align:center;">300</td><td>公司承接 + 个人职责 + 功能技术组成</td></tr><tr><td><strong>子题目一</strong></td><td style="text-align:center;">500-600</td><td>详细背景，理论+实际结合</td></tr><tr><td><strong>子题目二</strong></td><td style="text-align:center;">300</td><td>单独论点回应</td></tr><tr><td><strong>子题目三（核心）</strong></td><td style="text-align:center;">1000-1200</td><td>业务逻辑+技术实现，3-5 段</td></tr><tr><td><strong>结尾①</strong></td><td style="text-align:center;">200</td><td>套话+经验总结，呼应主题</td></tr><tr><td><strong>结尾②</strong></td><td style="text-align:center;">200</td><td>2 个不足及改进方法</td></tr></tbody></table><blockquote><p>建议总字数 2200-2700 字，2000 字以下会扣分，3000 字是上限。</p></blockquote><h4 id="摘要要点" tabindex="-1">摘要要点 <a class="header-anchor" href="#摘要要点" aria-label="Permalink to &quot;摘要要点&quot;">​</a></h4><ul><li>必写：项目时间、名称、岗位、功能作用</li><li>选写：项目金额、历时</li><li><strong>严格 300 字左右</strong>，逻辑分两段但实际写作不分段</li><li>模板示例：&quot;2021 年 3 月，我参与...项目，担任...。系统包括...功能模块，能够...。本文结合...&quot;</li></ul><h4 id="过渡技巧" tabindex="-1">过渡技巧 <a class="header-anchor" href="#过渡技巧" aria-label="Permalink to &quot;过渡技巧&quot;">​</a></h4><ul><li>背景→子题：说明技术引入原因（如&quot;因测试人员不足，故引入 AI 生成用例&quot;）</li><li>子题→正文：建立逻辑关联（如&quot;基于上述背景，我们实施以下方案&quot;）</li></ul><h4 id="结尾模板-弹性-400-600-字" tabindex="-1">结尾模板（弹性 400-600 字） <a class="header-anchor" href="#结尾模板-弹性-400-600-字" aria-label="Permalink to &quot;结尾模板（弹性 400-600 字）&quot;">​</a></h4><p>四段式：成果汇报 → 经验总结（呼应主题）→ 不足分析（通用小问题：人员流动/负载波动）→ 改进方向。</p><hr><h3 id="二、项目选择策略-★" tabindex="-1">二、项目选择策略 ★ <a class="header-anchor" href="#二、项目选择策略-★" aria-label="Permalink to &quot;二、项目选择策略 ★&quot;">​</a></h3><h4 id="推荐标准" tabindex="-1">推荐标准 <a class="header-anchor" href="#推荐标准" aria-label="Permalink to &quot;推荐标准&quot;">​</a></h4><blockquote><p>中大型商业项目，金额 <strong>200W 以上</strong>，研发周期 <strong>6 个月以上</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>示例</th><th style="text-align:center;">评分</th></tr></thead><tbody><tr><td>传统信息系统</td><td>国企/医院/银行的 ERP、OA</td><td style="text-align:center;">45-50（稳妥）</td></tr><tr><td>新兴技术项目</td><td>云计算/大数据相关</td><td style="text-align:center;">可达 65（但有风险）</td></tr></tbody></table><h4 id="不能选的项目" tabindex="-1">不能选的项目 <a class="header-anchor" href="#不能选的项目" aria-label="Permalink to &quot;不能选的项目&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>原因</th></tr></thead><tbody><tr><td><strong>小型系统</strong></td><td>图书馆管理/学生管理/进销存 → 评审无兴趣</td></tr><tr><td><strong>未完成项目</strong></td><td>必须已上线运行</td></tr><tr><td><strong>纯网站项目</strong></td><td>仅静态页面或简单交互</td></tr><tr><td><strong>硬件项目</strong></td><td>综合布线/安防/视频会议</td></tr><tr><td><strong>纯技术项目</strong></td><td>数据迁移/算法研究（应侧重业务实现）</td></tr></tbody></table><h4 id="零基础项目来源" tabindex="-1">零基础项目来源 <a class="header-anchor" href="#零基础项目来源" aria-label="Permalink to &quot;零基础项目来源&quot;">​</a></h4><ol><li>政府采购网：搜索&quot;XX 省政府采购网&quot;，用&quot;医院&quot;&quot;银行&quot;关键词筛选</li><li>AI 辅助构建：提示词示例 — &quot;开发 500 万预算、6 个月周期的银行 ERP 系统&quot;</li><li>注意：避免直接抄袭常见范文项目（评审已产生辨识度）</li></ol><hr><h3 id="三、论文写作常见问题" tabindex="-1">三、论文写作常见问题 <a class="header-anchor" href="#三、论文写作常见问题" aria-label="Permalink to &quot;三、论文写作常见问题&quot;">​</a></h3><h4 id="_1-字数分配" tabindex="-1">1. 字数分配 <a class="header-anchor" href="#_1-字数分配" aria-label="Permalink to &quot;1. 字数分配&quot;">​</a></h4><p>摘要 300 + 背景 500 + 主体 1200 + 结尾 500 = <strong>约 2500 字</strong>。</p><h4 id="_2-无架构师经验怎么办" tabindex="-1">2. 无架构师经验怎么办 <a class="header-anchor" href="#_2-无架构师经验怎么办" aria-label="Permalink to &quot;2. 无架构师经验怎么办&quot;">​</a></h4><ul><li>改写熟悉项目，岗位表述为技术中高层（系统分析师/CTO/技术负责人）</li><li>避免写普通程序员或测试人员角色</li><li>理论用自己的语言表述，不需死记硬背</li></ul><h4 id="_3-内部项目怎么写" tabindex="-1">3. 内部项目怎么写 <a class="header-anchor" href="#_3-内部项目怎么写" aria-label="Permalink to &quot;3. 内部项目怎么写&quot;">​</a></h4><ul><li>避免出现&quot;内部项目&quot;表述</li><li>按标准流程描述：&quot;某年某月公司启动 XX 项目&quot;</li><li>结尾统一使用&quot;客户一致满意&quot;</li></ul><h4 id="_4-项目背景如何构造" tabindex="-1">4. 项目背景如何构造 <a class="header-anchor" href="#_4-项目背景如何构造" aria-label="Permalink to &quot;4. 项目背景如何构造&quot;">​</a></h4><table tabindex="0"><thead><tr><th>要素</th><th>建议</th></tr></thead><tbody><tr><td><strong>时间</strong></td><td>考试前 5 年内，持续 ≥6 个月，<strong>必须已完成</strong></td></tr><tr><td><strong>级别</strong></td><td>省市级/集团级，避免县级/社区级</td></tr><tr><td><strong>名称</strong></td><td><strong>不能出现真实名称</strong>，用&quot;某省某市某医院&quot;模糊表述</td></tr><tr><td><strong>金额</strong></td><td>团队规模×时间估算（20 人×15 月≈600 万），避免整数用 565/618 万</td></tr></tbody></table><h4 id="_5-如何记住论文" tabindex="-1">5. 如何记住论文 <a class="header-anchor" href="#_5-如何记住论文" aria-label="Permalink to &quot;5. 如何记住论文&quot;">​</a></h4><ul><li>核心原则：<strong>所有内容必须自己改写</strong></li><li>建立固定模板框架，限时 2 小时默写</li><li>仅同批次查重，历史论文可复用</li></ul><h4 id="_6-论文题目" tabindex="-1">6. 论文题目 <a class="header-anchor" href="#_6-论文题目" aria-label="Permalink to &quot;6. 论文题目&quot;">​</a></h4><p>机考系统直接选择题号，无需手动填写。更换题目必须删除已作答内容。</p><hr><h3 id="四、论点构建方法论-★" tabindex="-1">四、论点构建方法论 ★ <a class="header-anchor" href="#四、论点构建方法论-★" aria-label="Permalink to &quot;四、论点构建方法论 ★&quot;">​</a></h3><h4 id="论点来源" tabindex="-1">论点来源 <a class="header-anchor" href="#论点来源" aria-label="Permalink to &quot;论点来源&quot;">​</a></h4><ol><li>直接转化子题目要求</li><li>参考教材标准分类（如软件维护 4 类型）</li><li>结合技术分层结构（如 Lambda 架构按层分层论述）</li></ol><h4 id="高频考点论点库" tabindex="-1">高频考点论点库 <a class="header-anchor" href="#高频考点论点库" aria-label="Permalink to &quot;高频考点论点库&quot;">​</a></h4><table tabindex="0"><thead><tr><th>考点</th><th>论点/关键点</th></tr></thead><tbody><tr><td><strong>事件驱动架构</strong></td><td>消息队列（异步通信）、订阅发布（观察者模式）、回调函数（前端拖拽触发）</td></tr><tr><td><strong>SOA</strong></td><td>需与微服务明确区分；阅卷容错度较高</td></tr><tr><td><strong>软件维护</strong></td><td>完善性（DevOps 持续部署）、质量特性（ISO 9126 维度）</td></tr><tr><td><strong>大数据架构</strong></td><td>Lambda：批处理层+速度层+服务层；湖仓一体</td></tr><tr><td><strong>测试技术</strong></td><td>单元测试：白盒（路径/条件覆盖）+ 黑盒（边界值/等价类）；AI 测试：提示词工程</td></tr></tbody></table><h4 id="应试策略" tabindex="-1">应试策略 <a class="header-anchor" href="#应试策略" aria-label="Permalink to &quot;应试策略&quot;">​</a></h4><ul><li>近年考过题目重复概率低，但相关技术知识点需掌握</li><li>偏题处理：必须回应所有子题目，正文含具体技术细节和案例</li><li><strong>论文结构完整度比绝对正确性更重要</strong></li></ul><hr><h3 id="五、历年真题趋势" tabindex="-1">五、历年真题趋势 <a class="header-anchor" href="#五、历年真题趋势" aria-label="Permalink to &quot;五、历年真题趋势&quot;">​</a></h3><p><strong>考试范围</strong>：软件架构理论与设计方法 / 系统建模与设计 / 系统可靠性与安全性 / 新兴技术与 IT 架构</p><p><strong>高频主题</strong>：架构风格与模式（微服务/层次化/事件驱动/CQRS）、架构评估（ATAM）、软件复用与构件、UML 建模、领域驱动设计（DDD）</p><blockquote><p>论文题目&quot;考过不重复&quot;，四选一降低难度，超纲不影响大局。</p></blockquote>',48)])])}const c=a(o,[["render",l]]);export{g as __pageData,c as default};
